import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static int lowerBound(long[] a, long v) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }


    static long[] mergeSorted(long[] x, long[] y) {
        long[] z = new long[x.length + y.length];
        int i = 0, j = 0, k = 0;
        while (i < x.length && j < y.length) {
            if (x[i] <= y[j]) z[k++] = x[i++];
            else z[k++] = y[j++];
        }
        while (i < x.length) z[k++] = x[i++];
        while (j < y.length) z[k++] = y[j++];
        return z;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long q = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[][] qs = new long[(int) q][3];
        for (int i = 0; i < qs.length; i++) {
            for (int j = 0; j < qs[i].length; j++) {
                qs[i][j] = Long.parseLong(next());
            }
        }

        int size = 1;
        while (size < n) size *= 2;
        long[][] tree = new long[2 * size][];
        for (int i = 0; i < size; i++) tree[size + i] = i < n ? new long[] {a[i]} : new long[0];
        for (int node = size - 1; node >= 1; node--) tree[node] = mergeSorted(tree[2 * node], tree[2 * node + 1]);
        long last = 0;
        StringBuilder out = new StringBuilder();
        for (int j = 0; j < q; j++) {
            int lo = (int) (qs[j][0] ^ last) - 1 + size;
            int hi = (int) (qs[j][1] ^ last) + size;
            long x = qs[j][2] ^ last;
            long cnt = 0;
            while (lo < hi) {
                if ((lo & 1) == 1) {
                    cnt += tree[lo].length - lowerBound(tree[lo], x + 1);
                    lo++;
                }
                if ((hi & 1) == 1) {
                    hi--;
                    cnt += tree[hi].length - lowerBound(tree[hi], x + 1);
                }
                lo >>= 1;
                hi >>= 1;
            }
            if (j > 0) out.append(" ");
            out.append(cnt);
            last = cnt;
        }
        System.out.println(out);
    }
}
